/**
 * The new-network prompt vectors: each case decodes through `decodeEvm` like any sign request and
 * renders through `chainPrompt` — the recorded verifiability and the exact en/zh-Hans prompts must
 * match. The cases are generated by packages/wallet-chains/scripts/evm-networks-vectors.ts with
 * expected text written by hand, not captured from kernel output.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { describe, expect, it } from "vite-plus/test";

import { decodeEvm } from "@qntx/wallet-chains/evm";

import { chainPrompt } from "../src/modules/chains/prompt.ts";
import type { KeystorePrompt } from "../src/platform.ts";

type VectorCase = {
  readonly name: string;
  readonly request: Parameters<typeof decodeEvm>[0];
  readonly verifiability: string;
  readonly blind: string | null;
  readonly prompt: Readonly<Record<"en" | "zh-Hans", KeystorePrompt>>;
};

const vectors = JSON.parse(
  readFileSync(resolve(import.meta.dirname, "../../../vectors/chains/evm-networks.json"), "utf8"),
) as { signer: string; cases: VectorCase[] };

const blindOf = (intent: { readonly blind?: string }): string | null => intent.blind ?? null;

/** The case named `name`, which must exist — keeps `?.`/`??` out of test bodies. */
const caseNamed = (name: string): VectorCase => {
  const found = vectors.cases.find((c) => c.name === name);
  if (found === undefined) {
    throw new Error(`missing vector case ${name}`);
  }
  return found;
};

describe("evm-networks vectors", () => {
  it.each(vectors.cases)("$name", (v) => {
    const intent = decodeEvm(v.request, vectors.signer);
    expect(intent.verifiability).toBe(v.verifiability);
    expect(blindOf(intent)).toBe(v.blind);
    expect(chainPrompt("en", intent)).toStrictEqual(v.prompt.en);
    expect(chainPrompt("zh-Hans", intent)).toStrictEqual(v.prompt["zh-Hans"]);
  });

  it("renders the longest network name in full — no prompt line is excerpted", () => {
    const intent = decodeEvm(
      caseNamed("Robinhood Chain Testnet native ETH transfer").request,
      vectors.signer,
    );
    const prompt = chainPrompt("en", intent);
    expect(prompt.description).toContain("Robinhood Chain Testnet");
    expect(prompt.description).not.toContain("…");
    // The kernel caps nothing on a rendered prompt; its excerpt bounds apply to untrusted content
    // (message text 320 code points over 6 lines, typed-data fields 96). The longest transfer
    // prompt stays far under either.
    expect(prompt.description.length).toBeLessThanOrEqual(320);
  });
});
